    """Contract for raw incoming telemetry."""
    node_id: Series[str] = pa.Field(str_matches=r"^node-\d+$")
    timestamp: Series[pd.Timestamp] = pa.Field()
    cpu_util: Series[float] = pa.Field(ge=0.0, le=100.0, nullable=True)
