# ---------------------------------------------------------------------------
# Clock Skew Correction
# ---------------------------------------------------------------------------

@dataclass
class ClockSkewResult:
    """Container for skew correction output."""
    corrected_df: pd.DataFrame
    skew_report: pd.DataFrame
    max_skew_seconds: float


class ClockSkewCorrector:
    """
    Detects and corrects clock skew across nodes using a reference timeline.

    Strategy:
        1. Compute per-node median inter-arrival time.
        2. Align each node's timeline to the global median timeline via
           quantile matching (robust to outliers).
        3. Apply linear interpolation to shift timestamps.
    """

    def __init__(self, reference_quantile: float = 0.5, max_skew_threshold_s: float = 300.0):
        self.reference_quantile = reference_quantile
        self.max_skew_threshold_s = max_skew_threshold_s

    def fit_transform(self, df: pd.DataFrame) -> ClockSkewResult:
        """Detect and correct skew. Returns corrected frame + diagnostic report."""
        if df.empty:
            return ClockSkewResult(df, pd.DataFrame(), 0.0)

        node_groups = df.groupby("node_id")
        global_timestamps = df["timestamp"].sort_values().values

        # Reference quantile timeline
        ref_ts = np.quantile(global_timestamps, self.reference_quantile)

        corrected_frames = []
        skew_rows = []

        for node_id, group in node_groups:
            node_ts = group["timestamp"].sort_values().values
            node_quantile = np.quantile(node_ts, self.reference_quantile)
            skew_s = float((node_quantile - ref_ts).total_seconds())

            if abs(skew_s) > self.max_skew_threshold_s:
                logger.warning("Node %s skew %.2fs exceeds threshold; correcting", node_id, skew_s)
                # Shift timestamps to align quantiles
                corrected_ts = group["timestamp"] - pd.Timedelta(seconds=skew_s)
                corrected_group = group.copy()
                corrected_group["timestamp"] = corrected_ts
                corrected_group["skew_corrected"] = True
            else:
                corrected_group = group.copy()
                corrected_group["skew_corrected"] = False

            corrected_frames.append(corrected_group)
            skew_rows.append({"node_id": node_id, "skew_seconds": skew_s, "corrected": abs(skew_s) > self.max_skew_threshold_s})

        corrected_df = pd.concat(corrected_frames, ignore_index=True)
        skew_report = pd.DataFrame(skew_rows)
        max_skew = float(skew_report["skew_seconds"].abs().max()) if not skew_report.empty else 0.0

        return ClockSkewResult(corrected_df, skew_report, max_skew)


# ---------------------------------------------------------------------------
# Missing Data Imputation
# ---------------------------------------------------------------------------

class MissingDataImputer:
    """
    Context-aware imputation for telemetry gaps.

    Strategy:
        - Forward-fill for short gaps (<= 2 intervals).
        - Linear interpolation for medium gaps (<= 10 intervals).
        - Rolling median fallback for longer gaps.
    """

    def __init__(self, max_ffill_gap: int = 2, max_interp_gap: int = 10):
        self.max_ffill_gap = max_ffill_gap
        self.max_interp_gap = max_interp_gap

    def transform(self, df: pd.DataFrame) -> pd.DataFrame:
        """Impute missing values in-place. Adds `imputed` flag column."""
        if df.empty:
            return df

        df = df.copy()
        df["imputed"] = False

        numeric_cols = ["cpu_util", "mem_util", "net_throughput", "task_queue_depth"]

        for col in numeric_cols:
            if col not in df.columns:
                continue

            # Track original NaN positions
            nan_mask = df[col].isna()
            if not nan_mask.any():
                continue

            # Group by node to avoid cross-node leakage
            for node_id, group_idx in df.groupby("node_id").groups.items():
                idx = group_idx
                col_vals = df.loc[idx, col]

                # Detect gap lengths
                is_nan = col_vals.isna().values
                gap_ids = self._find_gaps(is_nan)

                for gap_start, gap_end in gap_ids:
                    gap_len = gap_end - gap_start
                    if gap_len <= self.max_ffill_gap:
                        # Forward fill
                        df.loc[idx[gap_start:gap_end], col] = col_vals.iloc[:gap_start].ffill().iloc[-1] if gap_start > 0 else np.nan
                    elif gap_len <= self.max_interp_gap:
                        # Linear interpolation
                        df.loc[idx[gap_start:gap_end], col] = col_vals.interpolate(method="linear", limit_direction="both").iloc[gap_start:gap_end]
                    else:
                        # Rolling median fallback
                        median_val = col_vals.rolling(window=10, min_periods=1).median().iloc[gap_start:gap_end]
                        df.loc[idx[gap_start:gap_end], col] = median_val

                    df.loc[idx[gap_start:gap_end], "imputed"] = True

        # Final safety: fill any remaining NaN with column median
        for col in numeric_cols:
            if df[col].isna().any():
                df[col] = df[col].fillna(df[col].median())
                df.loc[df[col].isna(), "imputed"] = True  # Should not happen after fillna

        return df

    @staticmethod
    def _find_gaps(is_nan: np.ndarray) -> List[Tuple[int, int]]:
        """Find contiguous NaN regions as (start, end) index tuples."""
        gaps = []
        in_gap = False
        start = 0
        for i, val in enumerate(is_nan):
            if val and not in_gap:
                in_gap = True
                start = i
            elif not val and in_gap:
                in_gap = False
                gaps.append((start, i))
        if in_gap:
            gaps.append((start, len(is_nan)))
        return gaps


# ---------------------------------------------------------------------------
# Temporal Alignment
# ---------------------------------------------------------------------------

class TemporalAlignment:
    """
    Resamples telemetry to a fixed cadence per node.

    Uses mean aggregation for numeric columns, first for categorical.
    """

    def __init__(self, freq: str = "1min"):
        self.freq = freq

    def transform(self, df: pd.DataFrame) -> pd.DataFrame:
        """Resample to fixed frequency, grouped by node."""
        if df.empty:
            return df

        df = df.copy()
        df["timestamp"] = pd.to_datetime(df["timestamp"])
        df = df.set_index("timestamp")

        numeric_cols = ["cpu_util", "mem_util", "net_throughput", "task_queue_depth"]
        agg_dict = {col: "mean" for col in numeric_cols if col in df.columns}
        agg_dict["node_id"] = "first"

        resampled = df.groupby("node_id").resample(self.freq).agg(agg_dict).reset_index()
        return resampled


# ---------------------------------------------------------------------------
# Rolling Aggregations
# ---------------------------------------------------------------------------

class RollingAggregator:
    """Computes windowed statistics for feature enrichment."""

    def __init__(self, window: str = "5min", min_periods: int = 3):
        self.window = window
        self.min_periods = min_periods

    def transform(self, df: pd.DataFrame) -> pd.DataFrame:
        """Add rolling features."""
        if df.empty:
            return df

        df = df.copy()
        df = df.set_index("timestamp")

        grouped = df.groupby("node_id")

        df["cpu_util_rolling_mean_5m"] = grouped["cpu_util"].transform(
            lambda x: x.rolling(self.window, min_periods=self.min_periods).mean()
        )
        df["cpu_util_rolling_std_5m"] = grouped["cpu_util"].transform(
            lambda x: x.rolling(self.window, min_periods=self.min_periods).std()
        )
        df["mem_util_rolling_mean_5m"] = grouped["mem_util"].transform(
            lambda x: x.rolling(self.window, min_periods=self.min_periods).mean()
        )
        df["net_throughput_rolling_sum_5m"] = grouped["net_throughput"].transform(
            lambda x: x.rolling(self.window, min_periods=self.min_periods).sum()
        )
        df["task_queue_depth_rolling_max_5m"] = grouped["task_queue_depth"].transform(
            lambda x: x.rolling(self.window, min_periods=self.min_periods).max()
        )

        return df.reset_index()


