@dataclass
class FeaturePipelineConfig:
    """Configuration for the full pipeline."""
    resample_freq: str = "1min"
    rolling_window: str = "5min"
    rolling_min_periods: int = 3
    max_ffill_gap: int = 2
    max_interp_gap: int = 10
    max_skew_threshold_s: float = 300.0


class FeaturePipeline:
    """
    End-to-end feature engineering pipeline.

    Usage:
        pipeline = FeaturePipeline(config)
        processed_df = pipeline.run(raw_df)
    """

    def __init__(self, config: Optional[FeaturePipelineConfig] = None):
        self.config = config or FeaturePipelineConfig()
        self.skew_corrector = ClockSkewCorrector(max_skew_threshold_s=self.config.max_skew_threshold_s)
        self.imputer = MissingDataImputer(
            max_ffill_gap=self.config.max_ffill_gap,
            max_interp_gap=self.config.max_interp_gap,
        )
        self.aligner = TemporalAlignment(freq=self.config.resample_freq)
        self.aggregator = RollingAggregator(
            window=self.config.rolling_window,
            min_periods=self.config.rolling_min_periods,
        )

    def run(self, raw_df: pd.DataFrame) -> pd.DataFrame:
        """Execute the full pipeline with schema validation."""
        # Validate input
        try:
            DataFrame[RawTelemetrySchema].validate(raw_df, lazy=True)
        except pa.errors.SchemaErrors as e:
            logger.error("Input schema validation failed: %s", e)
            raise

        # Step 1: Clock skew correction
        skew_result = self.skew_corrector.fit_transform(raw_df)
        df = skew_result.corrected_df

        # Step 2: Missing data imputation
        df = self.imputer.transform(df)

        # Step 3: Temporal alignment
        df = self.aligner.transform(df)

        # Step 4: Rolling aggregations
        df = self.aggregator.transform(df)

        # Ensure required columns exist
        for col in ["skew_corrected", "imputed"]:
            if col not in df.columns:
                df[col] = False

        # Validate output
        try:
            DataFrame[ProcessedTelemetrySchema].validate(df, lazy=True)
        except pa.errors.SchemaErrors as e:
            logger.error("Output schema validation failed: %s", e)
            raise

        return df

    def get_skew_report(self) -> pd.DataFrame:
        """Return the latest skew correction report."""
        return self.skew_corrector.skew_report